<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · ChinaRouteMap</h1>
      <p class="demo-page__lead">
        来自 video-code 的「中国地图轨迹路线图」：canvas 上画中国轮廓和省份线，按经纬度铺路线和站点，
        点地图可以加站（自动找最近的景点 / 城市命名），播放时镜头放大跟着箭头走完全程。原 demo 是一整套
        路线编辑器（右侧列表拖动排序、录像导出、换箭头贴图、时长滑杆、缩放控件），组件里只保留可复用的核心：
        地图 + 路线 + 播放 / 缩放 / 加点。
      </p>
    </header>

    <section class="map-demo">
      <div class="map-demo__head">
        <h2 class="demo-page__section-title">点地图加点 · 播放镜头跟随</h2>
        <code class="map-demo__tag">{{ points.length }} 站</code>
      </div>
      <p class="demo-card__text">
        默认是原 demo 的五个景点（故宫 → 兵马俑 → 九寨沟 → 丽江古城 → 西湖）。在地图上点一下就能追加一站，
        滚轮缩放、拖动平移；点左下角「播放路线」看镜头跟着箭头走。
      </p>

      <div class="map-demo__toolbar">
        <button class="demo-btn" type="button" @click="play">播放路线</button>
        <button class="demo-btn demo-btn--ghost" type="button" @click="resetPoints">恢复示例路线</button>
        <button class="demo-btn demo-btn--ghost" type="button" :disabled="!points.length" @click="points = []">
          清空站点
        </button>
        <span class="map-demo__count">
          {{ playing ? '播放中…' : '已停止' }} · 最近新增：<code>{{ lastAdded }}</code>
        </span>
      </div>

      <div class="map-demo__stage">
        <ChinaRouteMap
          ref="mapRef"
          v-model:points="points"
          v-model:playing="playing"
          :duration="8"
          @add="onAdd"
        />
      </div>

      <div class="map-demo__row">
        <div class="map-demo__cell">
          <ChinaRouteMap
            :points="points.slice(0, 3)"
            :editable="false"
            :controls="false"
            :tip="false"
            :show-labels="false"
            :duration="5"
          />
          <p>只读版：3 站、无控件、不显示名称（适合当缩略图）</p>
        </div>
        <div class="map-demo__cell">
          <ChinaRouteMap
            :points="triangle"
            :editable="false"
            :controls="false"
            :tip="false"
            color="#0f766e"
            :duration="6"
          />
          <p>换主色 + 另一条路线（<code>color</code> / <code>points</code>）</p>
        </div>
      </div>
    </section>

    <DemoPreview class="map-preview">
      <LevaPlayground
        name="ChinaRouteMap"
        :component="ChinaRouteMap"
        :schema="ChinaRouteMapSchema"
        :presets="{ duration: 8, followZoom: 2.2 }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>duration</code> 是播放一遍的秒数，<code>followZoom</code> 是播放时的跟随放大倍数，
        <code>editable</code> 控制能否点地图加点，<code>showCities</code> / <code>showLabels</code> /
        <code>controls</code> / <code>tip</code> 是几处显示开关，<code>color</code> 是路线主色。
        <code>points</code> 是数组（面板不生成控件），要自定义路线直接传
        <code>:points="[{ name: '故宫', lon: 116.4, lat: 39.92 }]"</code>。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import ChinaRouteMapSchema from '@melt-js/comps-vue3/src/components/ChinaRouteMap.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const ChinaRouteMap = remoteComponent('ChinaRouteMap')

type RoutePoint = { name?: string; lon: number; lat: number }

const DEMO_ROUTE: RoutePoint[] = [
  { name: '故宫', lon: 116.4, lat: 39.92 },
  { name: '兵马俑', lon: 109.27, lat: 34.38 },
  { name: '九寨沟', lon: 103.92, lat: 33.25 },
  { name: '丽江古城', lon: 100.23, lat: 26.87 },
  { name: '西湖', lon: 120.14, lat: 30.25 },
]

const triangle: RoutePoint[] = [
  { name: '哈尔滨', lon: 126.53, lat: 45.8 },
  { name: '广州', lon: 113.26, lat: 23.13 },
  { name: '乌鲁木齐', lon: 87.62, lat: 43.82 },
]

const mapRef = ref<{ play: () => void; stop: () => void; reset: () => void } | null>(null)
const points = ref<RoutePoint[]>([...DEMO_ROUTE])
const playing = ref(false)
const lastAdded = ref('（还没加过）')

const stageStyle = {
  display: 'block',
  height: '520px',
  padding: '0',
  background: '#eef6ff',
}

function play() {
  mapRef.value?.play()
}

function resetPoints() {
  points.value = DEMO_ROUTE.map((point) => ({ ...point }))
  lastAdded.value = '（已恢复示例路线）'
}

function onAdd(point: RoutePoint) {
  lastAdded.value = `${point.name}（${point.lon.toFixed(1)}, ${point.lat.toFixed(1)}）`
}
</script>

